#!/usr/bin/env bash
# run_job5.sh -- drive the whole URAM288 fuzzing job (job 5).
#
# Usage (on the cluster, from the job directory):
#   ./run_job5.sh [PART] [OUT_ROOT]
#
# Defaults: PART=xcvu3p-ffvc1517-2-e, OUT_ROOT=./out
# Prerequisites: vivado on PATH, variants/ generated by
#   python3 gen_uram_variants.py uram_variant_table.tsv variants
# and probes/ generated by
#   python3 gen_uram_content_probes.py probes
# (or pass VARIANTS_DIR / PROBES_DIR to override those locations).
#
# Passes, in order:
#   A. Attribute sweep: v000 (baseline) then v001..v034 in manifest
#      order, one Vivado batch run per variant, via
#      run_uram_variant.tcl. 35 runs.
#   B. Content probes: p000 (baseline, all zero) then p001..p012 in
#      manifest order, one Vivado batch run per probe, via
#      run_uram_content_probe.tcl. 13 runs. After p012, the driver
#      checks the control: if out/p012/uram.rbt is identical to
#      out/p000/uram.rbt, the init file did not take effect and pass B
#      is void. The driver records CONTROL-FAIL in runs.txt and stops.
#   C. One URAM per column: resolve one site per URAM column with
#      pick_uram_columns.tcl, generate the column design with
#      gen_uram_column_design.py, run it once via run_uram_column.tcl.
#      1 run. The .ll file maps every column's cell to its frames.
#
# After each run, check uram.bit/.rbt/.ll plus post_route.dcp and
# run_info.txt exist; append one line per run to runs.txt (id,
# attribute/probe, variant, part, site, Vivado version, status). On
# any failure: record FAIL with the Vivado log tail, and STOP. A
# failed run is never silently skipped, and later runs never proceed
# past it, because a gap in the sweep would corrupt the diff
# analysis.
#
# Vivado runs are sequential, never parallel: each run is a full
# synthesis/place/route, and parallel runs on a shared cluster node
# would fight for memory and make failures uninterpretable.
#
# No em dashes anywhere.
set -u

PART="${1:-xcvu3p-ffvc1517-2-e}"
OUT_ROOT="${2:-./out}"
VARIANTS_DIR="${VARIANTS_DIR:-./variants}"
PROBES_DIR="${PROBES_DIR:-./probes}"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

if ! command -v vivado >/dev/null 2>&1; then
  echo "ERROR: vivado not on PATH" >&2
  exit 1
fi
if [ ! -f "$VARIANTS_DIR/manifest.tsv" ]; then
  echo "ERROR: $VARIANTS_DIR/manifest.tsv not found; run gen_uram_variants.py first" >&2
  exit 1
fi
if [ ! -f "$PROBES_DIR/manifest.tsv" ]; then
  echo "ERROR: $PROBES_DIR/manifest.tsv not found; run gen_uram_content_probes.py first" >&2
  exit 1
fi

mkdir -p "$OUT_ROOT"
RUNS_TXT="$OUT_ROOT/runs.txt"
{
  echo "job: 5 (URAM288 attribute sweep + content probes + one per column)"
  echo "part: $PART"
  echo "started: $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  echo "variants: $VARIANTS_DIR"
  echo "probes: $PROBES_DIR"
} > "$RUNS_TXT"

check_outputs() {
  # $1 = run dir. Prints missing outputs (empty when complete).
  local run_out="$1" missing=""
  for suffix in bit rbt ll; do
    if [ ! -f "$run_out/uram.$suffix" ]; then
      missing="$missing uram.$suffix"
    fi
  done
  for extra in post_route.dcp run_info.txt; do
    if [ ! -f "$run_out/$extra" ]; then
      missing="$missing $extra"
    fi
  done
  echo "$missing"
}

run_one() {
  # $1 = tcl script, $2 = run id, $3.. = tclargs (last arg is out dir).
  # Runs Vivado, checks outputs, logs the run. Returns 0 on OK.
  local tcl="$1" run_id="$2"
  shift 2
  local run_out="${@: -1}"
  mkdir -p "$run_out"
  if ! vivado -mode batch -source "$SCRIPT_DIR/$tcl" \
      -tclargs "$@" \
      > "$run_out/vivado.log" 2>&1; then
    echo "FAIL $run_id: vivado exited nonzero; see $run_out/vivado.log" >&2
    echo "$run_id\tFAIL vivado-nonzero" >> "$RUNS_TXT"
    return 1
  fi
  local missing
  missing="$(check_outputs "$run_out")"
  if [ -n "$missing" ]; then
    echo "FAIL $run_id: missing outputs:$missing" >&2
    echo "$run_id\tFAIL missing:$missing" >> "$RUNS_TXT"
    return 1
  fi
  local vivado_version
  vivado_version="$(grep '^vivado_version:' "$run_out/run_info.txt" | sed 's/^vivado_version: //')"
  echo "$run_id\tOK $vivado_version" >> "$RUNS_TXT"
  echo "OK $run_id"
  return 0
}

echo "resolving fixed URAM site on $PART ..."
vivado -mode batch -source "$SCRIPT_DIR/pick_uram_site.tcl" \
  -tclargs "$PART" "$OUT_ROOT/site.txt" > "$OUT_ROOT/pick_site.log" 2>&1
if [ ! -s "$OUT_ROOT/site.txt" ]; then
  echo "ERROR: site resolution failed; see $OUT_ROOT/pick_site.log" >&2
  echo "site resolution: FAIL (see pick_site.log)" >> "$RUNS_TXT"
  exit 1
fi
SITE="$(cat "$OUT_ROOT/site.txt")"
echo "site: $SITE" >> "$RUNS_TXT"
echo "fixed URAM site: $SITE"

echo "=== pass A: attribute sweep (35 runs) ==="
tail -n +2 "$VARIANTS_DIR/manifest.tsv" | while IFS="$(printf '\t')" read -r run_id attribute default variant verilog; do
  echo "=== $run_id ($attribute = $variant, default $default) ==="
  if ! run_one run_uram_variant.tcl "$run_id" "$PART" "$VARIANTS_DIR/$verilog" "$SITE" "$OUT_ROOT/$run_id"; then
    exit 1
  fi
done
status=$?
if [ "$status" -ne 0 ]; then
  echo "job 5 STOPPED in pass A; see $RUNS_TXT" >&2
  exit 1
fi

echo "=== pass B: content probes (13 runs) ==="
tail -n +2 "$PROBES_DIR/manifest.tsv" | while IFS="$(printf '\t')" read -r run_id probe verilog mem mem_sha; do
  echo "=== $run_id ($probe) ==="
  if ! run_one run_uram_content_probe.tcl "$run_id" "$PART" "$PROBES_DIR/$run_id" "$SITE" "$OUT_ROOT/$run_id"; then
    exit 1
  fi
done
status=$?
if [ "$status" -ne 0 ]; then
  echo "job 5 STOPPED in pass B; see $RUNS_TXT" >&2
  exit 1
fi

# Pass B control: the all-ones probe must differ from the all-zero
# baseline, or the init file did not take effect and pass B is void.
if cmp -s "$OUT_ROOT/p000/uram.rbt" "$OUT_ROOT/p012/uram.rbt"; then
  echo "FAIL pass B control: p012 (all ones) .rbt is identical to p000 (all zero); the init file did not take effect" >&2
  echo "pass B control: FAIL p012 .rbt identical to p000 .rbt; init mechanism void, no content diffs analyzed" >> "$RUNS_TXT"
  exit 1
fi
echo "pass B control: PASS p012 .rbt differs from p000 .rbt" >> "$RUNS_TXT"
echo "pass B control: p012 differs from p000, init file took effect"

echo "=== pass C: one URAM per column (1 run) ==="
vivado -mode batch -source "$SCRIPT_DIR/pick_uram_columns.tcl" \
  -tclargs "$PART" "$OUT_ROOT/column_sites.txt" > "$OUT_ROOT/pick_columns.log" 2>&1
if [ ! -s "$OUT_ROOT/column_sites.txt" ]; then
  echo "ERROR: column site resolution failed; see $OUT_ROOT/pick_columns.log" >&2
  echo "column site resolution: FAIL (see pick_columns.log)" >> "$RUNS_TXT"
  exit 1
fi
echo "column sites: $(wc -l < "$OUT_ROOT/column_sites.txt")" >> "$RUNS_TXT"
python3 "$SCRIPT_DIR/gen_uram_column_design.py" \
  "$OUT_ROOT/column_sites.txt" "$OUT_ROOT/column_design.v"
if ! run_one run_uram_column.tcl "col" "$PART" "$OUT_ROOT/column_design.v" "$OUT_ROOT/column_sites.txt" "$OUT_ROOT/col"; then
  echo "job 5 STOPPED in pass C; see $RUNS_TXT" >&2
  exit 1
fi

echo "finished: $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$RUNS_TXT"
echo "job 5 complete: $(grep -c $'\tOK ' "$RUNS_TXT") runs OK; see $RUNS_TXT"
